#include <linux/sched.h>
#include <linux/signal.h>
#include <linux/err.h>

int handle_waitid(int which, pid_t upid, struct siginfo __user *infop, int options, struct rusage __user *ru) {
    struct task_struct *task;
    int retval;

    task = find_get_task_by_vpid(upid);
    if (!task)
        return -ESRCH;

    if (!infop) {
        put_task_struct(task);
        return -EINVAL;
    }

    retval = 0;

    if (task->exit_state == 0) {
        put_task_struct(task);
        return -ECHILD;
    }

    if (copy_siginfo_to_user(infop, &task->pending.siginfo)) {
        put_task_struct(task);
        return -EFAULT;
    }

    if (ru && (options & WNOWAIT)) {
        if (do_getrusage(task, ru)) {
            put_task_struct(task);
            return -EFAULT;
        }
    }

    put_task_struct(task);
    return retval;
}

#include <sys/types.h>
