int sys_waitid(int which, pid_t upid, struct siginfo __user *infop, int options, struct rusage __user *ru) {
    struct rusage rusage_data;
    siginfo_t si;
    int ret;

    if ((options & ~(WALL | WNOHANG | WSTOPPED | WCONTINUED | WNOWAIT | WEXITED | WUNTRACED)) != 0) {
        return -EINVAL;
    }

    ret = waitid(which, upid, &si, options, ru ? &rusage_data : NULL);

    if (ret == -1) {
        return -errno;
    }

    if (infop) {
        if (copy_to_user(infop, &si, sizeof(si)) != 0) {
            return -EFAULT;
        }
    }

    if (ru) {
        if (copy_to_user(ru, &rusage_data, sizeof(rusage_data)) != 0) {
            return -EFAULT;
        }
    }

    return 0;
}

