SYSCALL_DEFINE5(waitid, int, which, pid_t, upid, struct siginfo __user *, infop,
                int, options, struct rusage __user *, ru)
{
    struct waitid_info info;
    int retval;

    if (options & ~(WSTOPPED | WCONTINUED | WNOHANG | WEXITED | WNOWAIT))
        return -EINVAL;

    if (infop && (verify_area_user(VERIFY_WRITE, infop, sizeof(*infop)) < 0))
        return -EFAULT;

    if (ru && (verify_area_user(VERIFY_WRITE, ru, sizeof(*ru)) < 0))
        return -EFAULT;

    info.flags = options;
    info.pid = upid;
    info.uid = 0;
    info.utime = 0;
    info.stime = 0;
    info.maxrss = 0;

    switch (which) {
    case P_PID:
        retval = do_wait_id(WAITID_PID, upid, &info, options);
        break;
    case P_PGID:
        retval = do_wait_id(WAITID_PGRP, upid, &info, options);
        break;
    case P_ALL:
        retval = do_wait_id(WAITID_ANY, 0, &info, options);
        break;
    default:
        return -EINVAL;
    }

    if (retval < 0)
        return retval;

    if (infop) {
        if (copy_siginfo_to_user(infop, &info.info.si) < 0)
            return -EFAULT;
    }

    if (ru) {
        struct rusage *r = (struct rusage *)__get_free_page(GFP_KERNEL);
        if (!r)
            return -ENOMEM;

        r->ru_utime.tv_sec = info.utime / 1000000;
        r->ru_utime.tv_usec = info.utime % 1000000;
        r->ru_stime.tv_sec = info.stime / 1000000;
        r->ru_stime.tv_usec = info.stime % 1000000;
        r->ru_maxrss = info.maxrss;

        if (copy_to_user(ru, r, sizeof(*ru)) < 0) {
            free_page((unsigned long)r);
            return -EFAULT;
        }

        free_page((unsigned long)r);
    }

    return 0;
}

#include <sys/types.h>
#include <sys/wait.h>
#include <sys/time.h>
#include <sys/resource.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

int handle_waitid(int which, pid_t upid, struct siginfo __user *infop, int options, struct rusage __user *ru) {
    struct rusage kru;
    struct siginfo ksiginfo;
    int ret;

    if (upid == 0) {
        errno = EINVAL;
        return -errno;
    }

    ret = waitid(which, upid, &ksiginfo, options, (ru == NULL) ? NULL : &kru);

    if (ret < 0) {
        return -errno;
    }

    if (infop != NULL) {
        if (copy_to_user(infop, &ksiginfo, sizeof(struct siginfo))) {
            return -EFAULT;
        }
    }

    if (ru != NULL) {
        if (copy_to_user(ru, &kru, sizeof(struct rusage))) {
            return -EFAULT;
        }
    }

    return 0;
}

#include <sys/types.h>
#include <sys/wait.h>
#include <sys/time.h>
#include <sys/resource.h>
#include <unistd.h>
#include <sys/user.h>
#include <signal.h>

int handle_waitid(int which, pid_t upid, struct siginfo __user *infop, int options, struct rusage __user *ru) {
    struct rusage rusage_data;
    struct siginfo siginfo_data;
    int ret;

    if (which < 0 || which > __WCLONE) {
        return -EINVAL;
    }

    if (infop) {
        // Clear the siginfo structure before populating it
        memset(&siginfo_data, 0, sizeof(struct siginfo));
    }

    // Perform the waitid call
    ret = waitid(which, upid, &siginfo_data, options, ru ? &rusage_data : NULL);

    if (ret < 0) {
        return ret;
    }

    // Copy the siginfo data to user space if required
    if (infop && copy_to_user(infop, &siginfo_data, sizeof(struct siginfo))) {
        return -EFAULT;
    }

    // Copy the resource usage data to user space if required
    if (ru && copy_to_user(ru, &rusage_data, sizeof(struct rusage))) {
        return -EFAULT;
    }

    return 0;
}
